        /// <summary>
        /// Pay creators with one card payment Pays exactly what is owed to the creators of a &#x60;treasury&#x60; campaign by charging the billing owner&#39;s saved card, with no redirect.  ### How it works  1. Every payable creator who finished payout setup (or only &#x60;participantIds&#x60;, minus &#x60;excludeParticipantIds&#x60;) is held in &#x60;settling&#x60;. 2. The saved card (the default one, or &#x60;paymentMethodId&#x60;) is charged the total plus the fee (4% per creator, 50 cent minimum) while the payer is present. 3. Once the charge succeeds, each creator gets a transfer funded by it, and the batch ends &#x60;paid&#x60; or &#x60;partially_failed&#x60;.  A creator whose payouts were disabled before the payment landed is skipped and stays payable.  ### 3D Secure  &#x60;payment.status: requires_action&#x60; means the bank asked the payer to confirm. Complete it with Stripe.js &#x60;handleNextAction({ clientSecret })&#x60;, then call &#x60;POST /v1/payout-batches/{batchId}/confirm&#x60;.  One left unfinished is cancelled after 30 minutes and every amount is payable again. Cancel it sooner with &#x60;POST /v1/payout-batches/{batchId}/cancel&#x60;.  ### Limits and errors  - 402 &#x60;payment_required&#x60;: no saved card. Nothing is held. - 402 &#x60;card_declined&#x60;: the bank&#39;s reason; every amount is payable again. - 402: card payouts are limited to $10,000.00 gross per rolling 30 days by default. Over it the call answers \&quot;Over your instant payout limit. Top up your balance to pay more this month, or contact support to raise the limit.\&quot; - 400: nothing payable (\&quot;Nothing is payable.\&quot;).  ### Access and retries  Needs an owner, admin or billing admin, signed in or through a full-access key they created.  Send an &#x60;Idempotency-Key&#x60; so a retry never opens a second batch. 
